package com.candyacademia.spsslite;

import javax.swing.*;import javax.swing.table.*;import java.awt.*;import java.io.*;import java.nio.file.*;import java.util.*;import java.util.List;

public final class Main extends JFrame{
    private static final long serialVersionUID = 1L;
    private DefaultTableModel model=DataSet.blank(30,6);private final JTable table=new JTable(model);private final JTextArea output=new JTextArea();private Path current;
    public Main(){super("Statistical Solutions");setDefaultCloseOperation(EXIT_ON_CLOSE);setSize(1100,720);setLocationRelativeTo(null);build();}
    private void build(){table.setAutoResizeMode(JTable.AUTO_RESIZE_OFF);table.setCellSelectionEnabled(true);table.setRowHeight(24);output.setEditable(false);output.setFont(new Font(Font.MONOSPACED,Font.PLAIN,13));JTabbedPane tabs=new JTabbedPane();tabs.addTab("Data Editor",new JScrollPane(table));tabs.addTab("Output",new JScrollPane(output));setJMenuBar(menu());add(tabs);}
    private JMenuBar menu(){JMenuBar b=new JMenuBar();JMenu file=new JMenu("File"),data=new JMenu("Data"),an=new JMenu("Analyze"),graphs=new JMenu("Graphs");item(file,"New",e->setModel(DataSet.blank(30,6)));item(file,"Open CSV…",e->open());item(file,"Save CSV",e->save(false));item(file,"Save CSV As…",e->save(true));item(file,"Export Output…",e->exportOutput());item(file,"Exit",e->dispose());item(data,"Add Row",e->model.addRow(new Object[model.getColumnCount()]));item(data,"Add Variable",e->model.addColumn("VAR"+(model.getColumnCount()+1)));item(data,"Rename Variable…",e->rename());item(an,"Descriptive Statistics…",e->descriptive());item(an,"Correlation Matrix…",e->correlation());item(an,"Linear Regression…",e->regression());item(an,"Independent-Samples t Test…",e->ttest());item(an,"Chi-Square Test…",e->chiSquare());item(graphs,"Histogram…",e->histogram());b.add(file);b.add(data);b.add(an);b.add(graphs);return b;}
    private void item(JMenu m,String name,java.awt.event.ActionListener a){JMenuItem i=new JMenuItem(name);i.addActionListener(a);m.add(i);}
    private void setModel(DefaultTableModel m){model=m;table.setModel(m);current=null;}
    private void open(){JFileChooser f=new JFileChooser();if(f.showOpenDialog(this)==JFileChooser.APPROVE_OPTION)try{current=f.getSelectedFile().toPath();setModel(DataSet.readCsv(current));this.current=f.getSelectedFile().toPath();}catch(Exception e){error(e);}}
    private void save(boolean as){try{if(as||current==null){JFileChooser f=new JFileChooser();if(f.showSaveDialog(this)!=JFileChooser.APPROVE_OPTION)return;current=f.getSelectedFile().toPath();}DataSet.writeCsv(model,current);}catch(Exception e){error(e);}}
    private void exportOutput(){JFileChooser f=new JFileChooser();if(f.showSaveDialog(this)==JFileChooser.APPROVE_OPTION)try{Files.writeString(f.getSelectedFile().toPath(),output.getText());}catch(Exception e){error(e);}}
    private void rename(){int c=table.getSelectedColumn();if(c<0){message("Select a column first.");return;}String s=JOptionPane.showInputDialog(this,"New variable name:",model.getColumnName(c));if(s!=null&&!s.isBlank())model.setColumnIdentifiers(headersWith(c,s.trim()));}
    private Object[] headersWith(int col,String name){Object[] h=new Object[model.getColumnCount()];for(int i=0;i<h.length;i++)h[i]=i==col?name:model.getColumnName(i);return h;}
    private JComboBox<String> combo(){JComboBox<String> c=new JComboBox<>();for(int i=0;i<model.getColumnCount();i++)c.addItem(model.getColumnName(i));return c;}
    private int chooseOne(String title){JComboBox<String> c=combo();if(JOptionPane.showConfirmDialog(this,c,title,JOptionPane.OK_CANCEL_OPTION)==JOptionPane.OK_OPTION)return c.getSelectedIndex();return-1;}
    private int[] chooseTwo(String title,String a,String b){JComboBox<String>x=combo(),y=combo();if(model.getColumnCount()>1)y.setSelectedIndex(1);JPanel p=new JPanel(new GridLayout(2,2,8,8));p.add(new JLabel(a));p.add(x);p.add(new JLabel(b));p.add(y);return JOptionPane.showConfirmDialog(this,p,title,JOptionPane.OK_CANCEL_OPTION)==JOptionPane.OK_OPTION?new int[]{x.getSelectedIndex(),y.getSelectedIndex()}:null;}
    private void descriptive(){int c=chooseOne("Select numeric variable");if(c<0)return;Statistics.Desc d=Statistics.describe(DataSet.numeric(model,c),model.getRowCount());append("DESCRIPTIVE STATISTICS\nVariable: %s\nN=%d  Missing=%d\nMean=%.6f  Median=%.6f  Std. Deviation=%.6f\nMinimum=%.6f  Maximum=%.6f\n".formatted(model.getColumnName(c),d.n(),d.missing(),d.mean(),d.median(),d.sd(),d.min(),d.max()));}
    private void correlation(){int[] c=chooseTwo("Pearson correlation","Variable 1","Variable 2");if(c==null)return;double[][]p=DataSet.paired(model,c[0],c[1]);double r=Statistics.correlation(p[0],p[1]);append("PEARSON CORRELATION\n%s × %s\nN=%d  r=%.6f\n".formatted(name(c[0]),name(c[1]),p[0].length,r));}
    private void regression(){int[]c=chooseTwo("Simple linear regression","Predictor (X)","Outcome (Y)");if(c==null)return;try{double[][]p=DataSet.paired(model,c[0],c[1]);var r=Statistics.regression(p[0],p[1]);append("SIMPLE LINEAR REGRESSION\nOutcome: %s | Predictor: %s\nN=%d  R=%.6f  R²=%.6f  Std. error=%.6f\nIntercept=%.6f  B=%.6f  t=%.6f  p=%.6g\nEquation: %s = %.6f + %.6f(%s)\n".formatted(name(c[1]),name(c[0]),r.n(),r.r(),r.r2(),r.se(),r.intercept(),r.slope(),r.t(),r.p(),name(c[1]),r.intercept(),r.slope(),name(c[0])));}catch(Exception e){error(e);}}
    private void ttest(){int[]c=chooseTwo("Independent-samples t test","Numeric outcome","Group variable (exactly 2 groups)");if(c==null)return;Map<String,List<Double>>g=new LinkedHashMap<>();for(int r=0;r<model.getRowCount();r++)try{String v=DataSet.text(model,r,c[0]),k=DataSet.text(model,r,c[1]);if(!v.isBlank()&&!k.isBlank())g.computeIfAbsent(k,z->new ArrayList<>()).add(Double.parseDouble(v));}catch(NumberFormatException ignored){}if(g.size()!=2){message("The grouping variable must contain exactly 2 non-empty groups.");return;}var it=g.entrySet().iterator();var a=it.next();var d=it.next();try{var t=Statistics.welch(a.getValue().stream().mapToDouble(Double::doubleValue).toArray(),d.getValue().stream().mapToDouble(Double::doubleValue).toArray());append("WELCH INDEPENDENT-SAMPLES t TEST\nOutcome: %s | Groups: %s vs %s\n%s: N=%d Mean=%.6f\n%s: N=%d Mean=%.6f\nt=%.6f  df=%.3f  p=%.6g\n".formatted(name(c[0]),a.getKey(),d.getKey(),a.getKey(),t.n1(),t.mean1(),d.getKey(),t.n2(),t.mean2(),t.t(),t.df(),t.p()));}catch(Exception e){error(e);}}
    private void chiSquare(){int[]c=chooseTwo("Chi-square test of independence","Row variable","Column variable");if(c==null)return;List<String>a=new ArrayList<>(),b=new ArrayList<>();for(int r=0;r<model.getRowCount();r++){String x=DataSet.text(model,r,c[0]),y=DataSet.text(model,r,c[1]);if(!x.isBlank()&&!y.isBlank()){a.add(x);b.add(y);}}try{var z=Statistics.chiSquare(a,b);StringBuilder s=new StringBuilder("CHI-SQUARE TEST OF INDEPENDENCE\n").append(name(c[0])).append(" × ").append(name(c[1])).append('\n');s.append(String.format("χ²=%.6f  df=%d  p=%.6g  N=%d\n",z.statistic(),z.df(),z.p(),a.size()));s.append("Observed counts:\n\t").append(String.join("\t",z.cols())).append('\n');for(int i=0;i<z.rows().length;i++){s.append(z.rows()[i]);for(int v:z.observed()[i])s.append('\t').append(v);s.append('\n');}append(s.toString());}catch(Exception e){error(e);}}
    private void histogram(){int c=chooseOne("Select numeric variable");if(c<0)return;JDialog d=new JDialog(this,"Histogram",false);d.add(new ChartPanel(name(c),DataSet.numeric(model,c)));d.pack();d.setLocationRelativeTo(this);d.setVisible(true);}
    private String name(int c){return model.getColumnName(c);}private void append(String s){output.append("\n"+s+"\n" );output.setCaretPosition(output.getDocument().getLength());}private void message(String s){JOptionPane.showMessageDialog(this,s);}private void error(Exception e){JOptionPane.showMessageDialog(this,e.getMessage(),"Error",JOptionPane.ERROR_MESSAGE);}
    public static void main(String[]args){SwingUtilities.invokeLater(()->{try{UIManager.setLookAndFeel(UIManager.getSystemLookAndFeelClassName());}catch(Exception ignored){}new Main().setVisible(true);});}
}
